// Node.js 示例代码 - CodeForge 代码执行环境

console.log("🎉 欢迎使用 CodeForge!");
console.log("Welcome to CodeForge!");
console.log("");

console.log("=========================================");
console.log("          CodeForge Node.js            ");
console.log("=========================================");
console.log("");

// 基本输出示例
console.log("✅ Node.js 运行成功! (Node.js is working!)");
console.log(`🟢 Node.js 版本 (Version): ${process.version}`);
console.log("");

// 简单计算
const number1 = 10;
const number2 = 20;
const result = number1 + number2;

console.log("🔢 简单计算 (Simple calculation):");
console.log(`${number1} + ${number2} = ${result}`);
console.log("");

// 字符串操作
const name = "CodeForge";
const platform = "Node.js";

console.log("📝 字符串操作 (String operations):");
console.log("平台名称 (Platform):", name);
console.log("运行环境 (Runtime):", platform);
console.log(`完整信息 (Full info): ${name} - ${platform}`);
console.log("");

// 循环示例
console.log("🔄 循环输出 (Loop output):");
for (let i = 1; i <= 5; i++) {
    console.log(`第 ${i} 次输出 (Output #${i}): Hello from CodeForge!`);
}

console.log("");

// 数组操作
const fruits = ["苹果", "香蕉", "橙子", "葡萄"];
console.log("🍎 水果列表 (Fruit list):");
fruits.forEach((fruit, index) => {
    console.log(`${index + 1}. ${fruit}`);
});

console.log("");

// 条件判断
const score = 85;
console.log("📊 成绩评估 (Score evaluation):");
if (score >= 90) {
    console.log("优秀! (Excellent!)");
} else if (score >= 80) {
    console.log("良好! (Good!)");
} else if (score >= 60) {
    console.log("及格 (Pass)");
} else {
    console.log("需要努力 (Need improvement)");
}

console.log("");

// JavaScript/Node.js 特性展示
console.log("🆕 JavaScript 特性 (JavaScript features):");
const data = { name: "CodeForge", platform: "Node.js", status: "运行中" };
console.log("对象操作 (Object):", JSON.stringify(data, null, 2));

// 箭头函数和数组方法
const squares = [1, 2, 3, 4, 5].map(x => x ** 2);
console.log("数组映射 (Array mapping):", squares);

// 异步操作示例
console.log("⏰ 异步操作 (Async operation):");
setTimeout(() => {
    console.log("⏱️  1秒后执行 (Executed after 1 second)");
}, 1000);

console.log("");
console.log("🎯 CodeForge Node.js 代码执行完成!");
console.log("🎯 CodeForge Node.js execution completed!");
console.log("");
console.log("感谢使用 CodeForge 代码执行环境! 🚀");
console.log("Thank you for using CodeForge! 🚀");
